  links: [{ t: 'FMCSA Clearinghouse — student driver page', u: 'https://clearinghouse.fmcsa.dot.gov/Learn/Student-Driver' }, { t: 'FMCSA — How do I get a commercial driver’s license?', u: 'https://www.fmcsa.dot.gov/registration/commercial-drivers-license/how-do-i-get-commercial-drivers-license' }]
